import React, { createContext, useContext, useState, ReactNode } from 'react';
import { User } from '../types';

interface AuthContextType {
  user: User | null;
  isAuthenticated: boolean;
  login: (email: string, password: string) => Promise<boolean>;
  register: (name: string, email: string, password: string) => Promise<boolean>;
  logout: () => void;
  getDashboard: () => Promise<any>;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (!context) throw new Error('useAuth must be used within AuthProvider');
  return context;
};

interface AuthProviderProps {
  children: ReactNode;
}

export const AuthProvider: React.FC<AuthProviderProps> = ({ children }) => {
  const [user, setUser] = useState<User | null>(null);
  const isAuthenticated = !!user;

  // Login usando el backend
  const login = async (email: string, password: string): Promise<boolean> => {
    try {
      const res = await fetch('http://localhost:4000/api/users/login', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email, password }),
      });

      if (!res.ok) return false;

      const data = await res.json();
      setUser(data.user);
      localStorage.setItem('token', data.token);
      return true;
    } catch (error) {
      console.error(error);
      return false;
    }
  };

  // Register usando el backend
  const register = async (name: string, email: string, password: string): Promise<boolean> => {
    try {
      const res = await fetch('http://localhost:4000/api/users/register', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email, password }),
      });

      if (!res.ok) return false;

      const data = await res.json();
      setUser(data.user);
      localStorage.setItem('token', data.token);
      return true;
    } catch (error) {
      console.error(error);
      return false;
    }
  };

const getDashboard = async (): Promise<any> => {
  try {
    const token = localStorage.getItem('token');
    if (!token) return null;

    const res = await fetch('http://localhost:4000/api/users/dashboard', {
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${token}`, // Token guardado al login/register
      },
    });

    if (!res.ok) return null;

    const data = await res.json();
    return data.dashboard;
  } catch (error) {
    console.error(error);
    return null;
  }
};

  const logout = () => {
    localStorage.removeItem('token');
    setUser(null);
  };


  return (
    <AuthContext.Provider value={{ user, isAuthenticated, login, register, logout, getDashboard }}>
      {children}
    </AuthContext.Provider>
  );
};
